function Write-SysLog {
    param(
        [string]$Message,
        [ValidateSet('INFO','WARN','ERROR','DEBUG')]
        [string]$Level = 'INFO',
        [string]$LogFile = $LogFilePath
    )
    $ts = Get-Date -Format 'yyyy-MM-dd HH:mm:ss'
    $entry = "[$ts] [$Level] $Message"
    if (-not (Test-Path (Split-Path $LogFile))) {
        New-Item -ItemType Directory -Path (Split-Path $LogFile) -Force | Out-Null
    }
    Add-Content -Path $LogFile -Value $entry -Encoding UTF8
    if ($Level -eq 'ERROR') { Write-Host $entry -ForegroundColor Red }
    elseif ($Level -eq 'WARN') { Write-Host $entry -ForegroundColor Yellow }
    else { Write-Host $entry -ForegroundColor Cyan }
}

function Send-AlertMail {
    param(
        [string]$To,
        [string]$Subject,
        [string]$Body,
        [string]$From = 'noreply@corp.local'
    )
    try {
        Send-MailMessage -SmtpServer $SMTPServer -From $From -To $To `
            -Subject $Subject -Body $Body -Encoding UTF8 -ErrorAction Stop
        Write-SysLog "Mail envoyé à $To : $Subject"
        return $true
    } catch {
        Write-SysLog "Échec envoi mail : $_" -Level 'ERROR'
        return $false
    }
}

function Invoke-CICDPipeline {
    param(
        [string]$PipelineName,
        [string]$Branch = 'main',
        [hashtable]$Variables = @{}
    )
    $headers = @{ 'Authorization' = "Bearer $CI_CD_TOKEN"; 'Content-Type' = 'application/json' }
    $body = @{ definitionName = $PipelineName; sourceBranch = $Branch; variables = $Variables } | ConvertTo-Json -Depth 3
    try {
        $run = Invoke-RestMethod -Uri "$CICD_API_URL/pipelines/run" -Method Post -Headers $headers -Body $body -ErrorAction Stop
        Write-SysLog "Pipeline déclenché : $PipelineName ($($run.runId))"
        return [PSCustomObject]@{ RunId=$run.runId; Status=$run.state; Url=$run.url }
    } catch {
        Write-SysLog "Échec déclenchement pipeline : $_" -Level 'ERROR'
        throw
    }
}

function Build-DockerImageDSI {
    param(
        [string]$ImageName,
        [string]$Tag = 'latest',
        [string]$DockerfilePath = './Dockerfile',
        [string]$RegistryUrl = $ContainerRegistry_URL
    )
    $fullImage = "$RegistryUrl/$ImageName`:$Tag"
    try {
        docker build -t $fullImage -f $DockerfilePath . -ErrorAction Stop | Out-Null
        docker push $fullImage -ErrorAction Stop | Out-Null
        Write-SysLog "Image buildée & pushée : $fullImage"
        return $true
    } catch {
        Write-SysLog "Échec build/push Docker : $_" -Level 'ERROR'
        return $false
    }
}

function Deploy-K8sManifestDSI {
    param(
        [string]$ManifestPath,
        [string]$Namespace = 'default',
        [string]$KubeConfig = $KubeConfig_Path
    )
    $env:KUBECONFIG = $KubeConfig
    try {
        kubectl apply -f $ManifestPath -n $Namespace -ErrorAction Stop
        $deploy = (kubectl get deployment -n $Namespace -o json | ConvertFrom-Json).items | Where-Object { $_.metadata.name -match 'app' } | Select-Object -First 1
        kubectl rollout status deployment/$($deploy.metadata.name) -n $Namespace --timeout=300s -ErrorAction Stop
        Write-SysLog "Déploiement K8s OK : $ManifestPath"
        return 'Completed'
    } catch {
        Write-SysLog "Échec déploiement K8s : $_" -Level 'ERROR'
        return 'Failed'
    }
}

function Invoke-ModelTrainingDSI {
    param(
        [string]$ScriptPath,
        [string]$DatasetUri,
        [string]$ComputeTarget = 'gpu-cluster',
        [hashtable]$HyperParams = @{}
    )
    try {
        $run = Submit-MLJob -Script $ScriptPath -Data $DatasetUri -Compute $ComputeTarget -Params $HyperParams -ErrorAction Stop
        while ($run.Status -notin 'Completed','Failed') { Start-Sleep -Seconds 15; $run = Get-MLJob $run.RunId }
        Write-SysLog "Entraînement terminé : $($run.RunId) | Statut : $($run.Status)"
        return $run
    } catch {
        Write-SysLog "Échec entraînement : $_" -Level 'ERROR'
        throw
    }
}

function Register-MLModelDSI {
    param(
        [string]$ModelName,
        [string]$ModelPath,
        [string]$Version,
        [hashtable]$Metrics = @{}
    )
    $headers = @{ 'X-DSI-Token' = $CI_CD_TOKEN }
    $body = @{ name=$ModelName; path=$ModelPath; version=$Version; metrics=$Metrics } | ConvertTo-Json
    try {
        $res = Invoke-RestMethod -Uri "$ML_Registry_URI/models" -Method Post -Headers $headers -Body $body -ErrorAction Stop
        Write-SysLog "Modèle enregistré : $($res.modelId) v$Version"
        return $res.modelId
    } catch {
        Write-SysLog "Échec registre modèle : $_" -Level 'ERROR'
        throw
    }
}

function Get-ModelDriftMetricsDSI {
    param(
        [string]$EndpointUrl,
        [string]$BaselineDataset,
        [double]$Threshold = $DriftThreshold
    )
    try {
        $live = Invoke-RestMethod "$EndpointUrl/sampling" -ErrorAction Stop
        $driftScore = Calculate-PSI -Target $live -Reference $BaselineDataset
        $alert = $driftScore -gt $Threshold
        Write-SysLog "Drift ML : $driftScore (Seuil: $Threshold) | Alerte: $alert"
        return [PSCustomObject]@{ PSI=$driftScore; Threshold=$Threshold; DriftDetected=$alert; Timestamp=(Get-Date) }
    } catch {
        Write-SysLog "Échec calcul drift : $_" -Level 'ERROR'
        throw
    }
}

function Apply-TerraformDSI {
    param(
        [string]$Workspace,
        [string]$VarFile = 'terraform.tfvars',
        [switch]$AutoApprove
    )
    try {
        terraform workspace select $Workspace -ErrorAction Stop
        terraform init -input=false -ErrorAction Stop
        $plan = terraform plan -var-file=$VarFile -detailed-exitcode -out=tfplan -ErrorAction Stop
        if ($LastExitCode -eq 0) { return [PSCustomObject]@{ Action='NoChange'; Status='OK' } }
        if ($AutoApprove) {
            terraform apply tfplan -ErrorAction Stop
            Write-SysLog "IaC appliqué sur workspace $Workspace"
        } else {
            Write-SysLog "Plan généré : $Workspace (validation manuelle requise)" -Level 'WARN'
        }
        return [PSCustomObject]@{ Action='Applied'; Status='OK'; PlanSummary=$plan }
    } catch {
        Write-SysLog "Échec Terraform : $_" -Level 'ERROR'
        throw
    }
}

function Promote-EnvironmentDSI {
    param(
        [string]$ServiceName,
        [string]$SourceEnv,
        [string]$TargetEnv,
        [string]$Version = 'latest'
    )
    try {
        $artifact = Get-Artifact -Service $ServiceName -Version $Version -Env $SourceEnv
        Publish-Artifact -Service $ServiceName -Version $artifact.Version -Env $TargetEnv -Force
        $health = Invoke-HealthCheck -Url "$ServiceName.corp.local/health" -MaxRetries 5
        if (-not $health.Ok) { throw "Healthcheck échoué post-promotion" }
        Write-SysLog "$ServiceName promu $SourceEnv → $TargetEnv (v$Version)"
        return $true
    } catch {
        Write-SysLog "Échec promotion : $_" -Level 'ERROR'
        return $false
    }
}

public static string ReadFileContent(string filePath, string encoding = "UTF8") {
    return File.ReadAllText(filePath, Encoding.GetEncoding(encoding));
}

public static void WriteLog(string message, string level = "INFO") {
    Console.WriteLine($"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] [{level}] {message}");
}

function New-ADUserDSI {
    param(
        [string]$GivenName,
        [string]$Surname,
        [string]$Department,
        [string]$OU = $DefaultOUUsers,
        [string[]]$BaseGroups = @('GRP_Utilisateurs'),
        [string]$TempPassword = 'P@ss_Temp2025!'
    )
    $sam = ($GivenName.Substring(0,1) + $Surname).ToLower() -replace '[^a-z0-9]',''
    $upn = "$sam@$DomainFQDN"
    $secPwd = ConvertTo-SecureString $TempPassword -AsPlainText -Force
    try {
        $user = New-ADUser -GivenName $GivenName -Surname $Surname `
            -Name "$GivenName $Surname" -SamAccountName $sam `
            -UserPrincipalName $upn -Department $Department `
            -Path $OU -AccountPassword $secPwd `
            -ChangePasswordAtLogon $true -Enabled $true -PassThru
        foreach ($grp in $BaseGroups) { Add-ADGroupMember -Identity $grp -Members $sam -ErrorAction SilentlyContinue }
        Write-SysLog "Utilisateur créé : $sam ($upn)" -Level 'INFO'
        return $user
    } catch {
        Write-SysLog "Erreur création utilisateur $sam : $_" -Level 'ERROR'
        throw
    }
}

function Disable-ADUserDSI {
    param(
        [string]$SamAccountName,
        [string]$Reason,
        [string]$ArchiveOU = 'OU=Archives,DC=corp,DC=local'
    )
    try {
        $user = Get-ADUser -Identity $SamAccountName -Properties MemberOf
        Disable-ADAccount -Identity $SamAccountName
        $user.MemberOf | ForEach-Object { Remove-ADGroupMember -Identity $_ -Members $SamAccountName -Confirm:$false -ErrorAction SilentlyContinue }
        Move-ADObject -Identity $user.DistinguishedName -TargetPath $ArchiveOU
        Set-ADUser -Identity $SamAccountName -Description "DESACTIVE $(Get-Date -f yyyy-MM-dd) - $Reason"
        Write-SysLog "Compte désactivé : $SamAccountName | Motif : $Reason" -Level 'WARN'
    } catch {
        Write-SysLog "Erreur désactivation $SamAccountName : $_" -Level 'ERROR'
        throw
    }
}

function Get-ADGroupMembersDSI {
    param(
        [string]$GroupName,
        [switch]$Recursive,
        [switch]$EnabledOnly
    )
    $members = Get-ADGroupMember -Identity $GroupName -Recursive:$Recursive | Where-Object { $_.objectClass -eq 'user' }
    $result = foreach ($m in $members) {
        $u = Get-ADUser $m -Properties Enabled, LastLogonDate, EmailAddress
        if ($EnabledOnly -and -not $u.Enabled) { continue }
        [PSCustomObject]@{
            Name           = $u.Name
            SamAccountName = $u.SamAccountName
            Enabled        = $u.Enabled
            LastLogon      = $u.LastLogonDate
            Mail           = $u.EmailAddress
        }
    }
    return $result
}

function Set-ADUserOU {
    param([string]$SamAccountName, [string]$TargetOU)
    $dn = (Get-ADUser -Identity $SamAccountName).DistinguishedName
    Move-ADObject -Identity $dn -TargetPath $TargetOU
    Write-SysLog "Objet $SamAccountName déplacé vers $TargetOU"
}

function Sync-ADGroup {
    param([string]$GroupName, [string[]]$ReferenceList, [switch]$WhatIf)
    $current = (Get-ADGroupMember $GroupName | Where-Object objectClass -eq 'user').SamAccountName
    $toAdd    = $ReferenceList | Where-Object { $_ -notin $current }
    $toRemove = $current       | Where-Object { $_ -notin $ReferenceList }
    if (-not $WhatIf) {
        if ($toAdd)    { Add-ADGroupMember    -Identity $GroupName -Members $toAdd    -ErrorAction Continue }
        if ($toRemove) { Remove-ADGroupMember -Identity $GroupName -Members $toRemove -ErrorAction Continue }
    }
    Write-SysLog "Sync $GroupName : +$($toAdd.Count) / -$($toRemove.Count)" -Level ($WhatIf ? 'DEBUG' : 'INFO')
    return [PSCustomObject]@{ Added=$toAdd; Removed=$toRemove; Unchanged=($current | Where-Object { $_ -in $ReferenceList }) }
}

function New-NTFSShare {
    param(
        [string]$FolderPath,
        [string]$ShareName,
        [string[]]$ReadGroups  = @(),
        [string[]]$WriteGroups = @(),
        [string[]]$FullGroups  = @('GRP_Admins_SI')
    )
    if (-not (Test-Path $FolderPath)) { New-Item -ItemType Directory -Path $FolderPath -Force | Out-Null }
    New-SmbShare -Name $ShareName -Path $FolderPath -FullAccess 'Everyone' -ErrorAction Stop
    $acl = Get-Acl $FolderPath
    $acl.SetAccessRuleProtection($true, $false)
    foreach ($g in $ReadGroups)  { $acl.AddAccessRule([System.Security.AccessControl.FileSystemAccessRule]::new($g,'Read','ContainerInherit,ObjectInherit','None','Allow')) }
    foreach ($g in $WriteGroups) { $acl.AddAccessRule([System.Security.AccessControl.FileSystemAccessRule]::new($g,'Modify','ContainerInherit,ObjectInherit','None','Allow')) }
    foreach ($g in $FullGroups)  { $acl.AddAccessRule([System.Security.AccessControl.FileSystemAccessRule]::new($g,'FullControl','ContainerInherit,ObjectInherit','None','Allow')) }
    Set-Acl -Path $FolderPath -AclObject $acl
    Write-SysLog "Partage créé : \\$(hostname)\$ShareName → $FolderPath"
}

function Get-ShareAudit {
    param([string]$ComputerName = $env:COMPUTERNAME)
    Get-SmbShare -CimSession $ComputerName | ForEach-Object {
        $share = $_
        $perms = Get-SmbShareAccess -Name $share.Name -CimSession $ComputerName
        [PSCustomObject]@{
            Server    = $ComputerName
            Share     = $share.Name
            Path      = $share.Path
            Remark    = $share.Description
            Permissions = ($perms | Select-Object AccountName, AccessControlType, AccessRight)
        }
    }
}

function Install-WindowsUpdates {
    param([switch]$AcceptAll, [switch]$AutoReboot, [string[]]$ExcludeKBs = @())
    if (-not (Get-Module -ListAvailable PSWindowsUpdate)) {
        Install-Module PSWindowsUpdate -Force -Scope CurrentUser
    }
    Import-Module PSWindowsUpdate
    $params = @{ AcceptAll = $AcceptAll; AutoReboot = $AutoReboot; Verbose = $true }
    if ($ExcludeKBs) { $params['NotKBArticleID'] = $ExcludeKBs }
    $result = Get-WindowsUpdate @params -Install
    Write-SysLog "MAJ appliquées : $($result.Count) | Reboot requis : $(Get-WURebootStatus -Silent)"
    return $result
}

function Get-PendingUpdates {
    param([string[]]$ComputerNames = @($env:COMPUTERNAME))
    foreach ($pc in $ComputerNames) {
        try {
            $session = New-CimSession -ComputerName $pc -ErrorAction Stop
            $updates = Invoke-CimMethod -Namespace 'root/Microsoft/Windows/WindowsUpdate' `
                -ClassName 'MSFT_WUOperations' -MethodName 'ScanForUpdates' `
                -Arguments @{SearchCriteria='IsInstalled=0'} -CimSession $session
            [PSCustomObject]@{ Computer=$pc; PendingCount=$updates.Updates.Count; Updates=$updates.Updates }
        } catch {
            [PSCustomObject]@{ Computer=$pc; PendingCount='ERROR'; Updates=$_.Exception.Message }
        }
    }
}

function Test-NetworkDiag {
    param([string]$Target, [int]$Port = 443, [string]$DnsServer = '')
    $ping = Test-Connection -ComputerName $Target -Count 4 -Quiet
    $lat  = (Test-Connection -ComputerName $Target -Count 4 | Measure-Object -Property ResponseTime -Average).Average
    $dns  = if ($DnsServer) { Resolve-DnsName $Target -Server $DnsServer -ErrorAction SilentlyContinue }
            else             { Resolve-DnsName $Target -ErrorAction SilentlyContinue }
    $tcpTest = Test-NetConnection -ComputerName $Target -Port $Port -WarningAction SilentlyContinue
    $trace = tracert -d $Target 2>&1
    $report = [PSCustomObject]@{
        Target    = $Target
        Ping      = $ping
        AvgLatencyMs = [math]::Round($lat, 1)
        DNSRecord = $dns.IPAddress -join ', '
        PortOpen  = $tcpTest.TcpTestSucceeded
        Port      = $Port
        TraceRoute = $trace
    }
    Write-SysLog "Diag réseau $Target : Ping=$ping | Latence=${lat}ms | Port $Port=$($tcpTest.TcpTestSucceeded)"
    return $report
}

function Get-NetworkAdapterInfo {
    param([string]$ComputerName = $env:COMPUTERNAME)
    Get-NetIPConfiguration -CimSession $ComputerName | ForEach-Object {
        [PSCustomObject]@{
            Adapter    = $_.InterfaceAlias
            IPAddress  = ($_.IPv4Address.IPAddress -join ', ')
            Prefix     = ($_.IPv4Address.PrefixLength -join ', ')
            Gateway    = $_.IPv4DefaultGateway.NextHop
            DNS        = ($_.DNSServer.ServerAddresses -join ', ')
            MACAddress = (Get-NetAdapter -Name $_.InterfaceAlias -CimSession $ComputerName -ErrorAction SilentlyContinue).MacAddress
        }
    }
}

function Get-OpenPorts {
    param([string]$ComputerName = $env:COMPUTERNAME, [string]$Protocol = 'TCP')
    $connections = Invoke-Command -ComputerName $ComputerName -ScriptBlock {
        param($proto)
        $ports = if ($proto -in 'TCP','Both') { Get-NetTCPConnection -State Listen } else { @() }
        $ports += if ($proto -in 'UDP','Both') { Get-NetUDPEndpoint } else { @() }
        $ports | ForEach-Object {
            $proc = Get-Process -Id $_.OwningProcess -ErrorAction SilentlyContinue
            [PSCustomObject]@{ Port=$_.LocalPort; Protocol=$proto; PID=$_.OwningProcess; Process=$proc.Name }
        }
    } -ArgumentList $Protocol
    return $connections | Sort-Object Port
}

function Set-DNSEntry {
    param([string]$ZoneName, [string]$RecordName, [string]$IPAddress, [string]$DNSServer = $DomainController)
    $existing = Get-DnsServerResourceRecord -ZoneName $ZoneName -Name $RecordName -RRType A -ComputerName $DNSServer -ErrorAction SilentlyContinue
    if ($existing) {
        Remove-DnsServerResourceRecord -ZoneName $ZoneName -Name $RecordName -RRType A -ComputerName $DNSServer -Force
    }
    Add-DnsServerResourceRecordA -ZoneName $ZoneName -Name $RecordName -IPv4Address $IPAddress -ComputerName $DNSServer
    Write-SysLog "DNS : $RecordName.$ZoneName → $IPAddress (serveur $DNSServer)"
}

function Get-SystemInventory {
    param([string]$ComputerName = $env:COMPUTERNAME, [switch]$IncludeSoftware)
    $cs   = Get-CimInstance Win32_ComputerSystem  -ComputerName $ComputerName
    $os   = Get-CimInstance Win32_OperatingSystem  -ComputerName $ComputerName
    $cpu  = Get-CimInstance Win32_Processor        -ComputerName $ComputerName
    $bios = Get-CimInstance Win32_BIOS             -ComputerName $ComputerName
    $disk = Get-CimInstance Win32_LogicalDisk       -ComputerName $ComputerName -Filter "DriveType=3"
    $ram  = [math]::Round($cs.TotalPhysicalMemory/1GB, 2)
    $sw   = if ($IncludeSoftware) {
                Get-CimInstance Win32_Product -ComputerName $ComputerName | Select-Object Name, Version, Vendor
            } else { @() }
    [PSCustomObject]@{
        Computer   = $ComputerName
        Model      = "$($cs.Manufacturer) $($cs.Model)"
        SerialNo   = $bios.SerialNumber
        OS         = "$($os.Caption) $($os.Version)"
        CPU        = $cpu.Name
        RAM_GB     = $ram
        Disks      = $disk | Select-Object DeviceID, @{n='Size_GB';e={[math]::Round($_.Size/1GB,1)}}, @{n='Free_GB';e={[math]::Round($_.FreeSpace/1GB,1)}}
        Software   = $sw
        CollectedAt = Get-Date
    }
}

function Get-DiskHealth {
    param([string]$ComputerName = $env:COMPUTERNAME, [int]$ThresholdPct = 15)
    $disks = Get-CimInstance Win32_LogicalDisk -ComputerName $ComputerName -Filter 'DriveType=3'
    foreach ($d in $disks) {
        $total   = [math]::Round($d.Size/1GB, 1)
        $free    = [math]::Round($d.FreeSpace/1GB, 1)
        $pctFree = [math]::Round(($d.FreeSpace/$d.Size)*100, 1)
        $alert   = $pctFree -le $ThresholdPct
        if ($alert) { Write-SysLog "ALERTE espace disque $($d.DeviceID) sur $ComputerName : $pctFree% libre" -Level 'WARN' }
        [PSCustomObject]@{ Computer=$ComputerName; Drive=$d.DeviceID; Total_GB=$total; Free_GB=$free; FreePct=$pctFree; Alert=$alert }
    }
}

function Manage-WindowsService {
    param(
        [string]$ServiceName,
        [ValidateSet('Start','Stop','Restart','SetStartup')][string]$Action,
        [string]$StartupType = 'Automatic',
        [string]$ComputerName = $env:COMPUTERNAME
    )
    switch ($Action) {
        'Start'      { Start-Service   -Name $ServiceName -ComputerName $ComputerName }
        'Stop'       { Stop-Service    -Name $ServiceName -ComputerName $ComputerName -Force }
        'Restart'    { Restart-Service -Name $ServiceName -ComputerName $ComputerName -Force }
        'SetStartup' { Set-Service     -Name $ServiceName -ComputerName $ComputerName -StartupType $StartupType }
    }
    $svc = Get-Service -Name $ServiceName -ComputerName $ComputerName
    Write-SysLog "Service $ServiceName sur $ComputerName : Action=$Action | État=$($svc.Status)"
    return $svc
}

function Get-ServiceHealth {
    param([string[]]$CriticalServices, [string]$ComputerName = $env:COMPUTERNAME, [string]$AlertEmail = '')
    $results = foreach ($svc in $CriticalServices) {
        $s = Get-Service -Name $svc -ComputerName $ComputerName -ErrorAction SilentlyContinue
        $ok = $s -and $s.Status -eq 'Running'
        if (-not $ok) {
            Write-SysLog "SERVICE ARRÊTÉ : $svc sur $ComputerName" -Level 'ERROR'
            if ($AlertEmail) { Send-AlertMail -To $AlertEmail -Subject "[ALERTE] Service $svc arrêté" -Body "Le service $svc sur $ComputerName est arrêté." }
        }
        [PSCustomObject]@{ Computer=$ComputerName; Service=$svc; Status=$s.Status; Healthy=$ok }
    }
    return $results
}

function Get-SecurityEvents {
    param(
        [string]$ComputerName = $DomainController,
        [int[]]$EventIDs = $CriticalEventIDs,
        [int]$HoursBack = 24
    )
    $since  = (Get-Date).AddHours(-$HoursBack)
    $filter = @{ LogName='Security'; Id=$EventIDs; StartTime=$since }
    Get-WinEvent -FilterHashtable $filter -ComputerName $ComputerName -ErrorAction SilentlyContinue | ForEach-Object {
        [PSCustomObject]@{
            TimeCreated = $_.TimeCreated
            EventID     = $_.Id
            Level       = $_.LevelDisplayName
            Message     = $_.Message.Substring(0, [Math]::Min(200, $_.Message.Length))
            Computer    = $_.MachineName
        }
    }
}

function Get-LockedADAccounts {
    param([string]$SearchBase = $DefaultOUUsers)
    $locked = Search-ADAccount -LockedOut -SearchBase $SearchBase -UsersOnly
    foreach ($u in $locked) {
        $lockEvent = Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4740} -ComputerName $DomainController -MaxEvents 100 -ErrorAction SilentlyContinue |
            Where-Object { $_.Properties[0].Value -eq $u.SamAccountName } | Select-Object -First 1
        [PSCustomObject]@{
            SamAccountName = $u.SamAccountName
            Name           = $u.Name
            LockedOutTime  = $u.AccountLockoutTime
            LockSource     = $lockEvent.Properties[1].Value
            LockSourceIP   = $lockEvent.Properties[19].Value
        }
    }
}

function Invoke-SecurityBaseline {
    param([string]$ComputerName = $env:COMPUTERNAME)
    $fw      = (Get-NetFirewallProfile -CimSession $ComputerName | Where-Object Enabled -eq $true).Count -ge 1
    $bl      = (Get-BitLockerVolume -CimSession $ComputerName -ErrorAction SilentlyContinue | Where-Object ProtectionStatus -eq 'On').Count -ge 1
    $uac     = Invoke-Command $ComputerName { (Get-ItemProperty 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Policies\System').EnableLUA -eq 1 }
    $av      = (Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -CimSession $ComputerName -ErrorAction SilentlyContinue | Where-Object productState -ne 397568).Count -ge 1
    $pwdAge  = (Get-ADDefaultDomainPasswordPolicy).MaxPasswordAge.Days -le $MaxPasswordAgeDays
    $report  = [PSCustomObject]@{ Computer=$ComputerName; Firewall=$fw; BitLocker=$bl; UAC=$uac; Antivirus=$av; PasswordPolicy=$pwdAge; Compliant=($fw -and $bl -and $uac -and $av -and $pwdAge) }
    if (-not $report.Compliant) { Write-SysLog "Baseline NON CONFORME sur $ComputerName" -Level 'WARN' }
    return $report
}

function Get-ADComputersList {
    param([string]$SearchBase = $DefaultOUComputers, [switch]$PingCheck, [string]$OSFilter = '*')
    $computers = Get-ADComputer -Filter "OperatingSystem -like '$OSFilter'" -SearchBase $SearchBase `
        -Properties OperatingSystem, OperatingSystemVersion, LastLogonDate, IPv4Address, Description
    foreach ($c in $computers) {
        $online = if ($PingCheck) { Test-Connection -ComputerName $c.Name -Count 1 -Quiet } else { $null }
        [PSCustomObject]@{
            Name        = $c.Name
            OS          = $c.OperatingSystem
            OSVersion   = $c.OperatingSystemVersion
            IP          = $c.IPv4Address
            LastLogon   = $c.LastLogonDate
            Description = $c.Description
            Online      = $online
        }
    }
}

function Apply-GPODSIBaseline {
    param([string[]]$ComputerNames, [switch]$LogonScripts)
    foreach ($pc in $ComputerNames) {
        try {
            $args = if ($LogonScripts) { '/force /logoff' } else { '/force' }
            Invoke-Command -ComputerName $pc -ScriptBlock { param($a); Start-Process gpupdate -ArgumentList $a -Wait } -ArgumentList $args
            [PSCustomObject]@{ Computer=$pc; Status='OK'; Time=Get-Date }
            Write-SysLog "GPO rafraîchies sur $pc"
        } catch {
            [PSCustomObject]@{ Computer=$pc; Status="ERROR: $_"; Time=Get-Date }
            Write-SysLog "Échec GPO sur $pc : $_" -Level 'ERROR'
        }
    }
}

function New-LocalAdminAccount {
    param([string]$ComputerName = $env:COMPUTERNAME, [string]$Username, [string]$Password, [switch]$DisableDefault)
    $secPwd = ConvertTo-SecureString $Password -AsPlainText -Force
    Invoke-Command -ComputerName $ComputerName -ScriptBlock {
        param($u, $p, $dd)
        $newUser = New-LocalUser -Name $u -Password $p -PasswordNeverExpires $false -ErrorAction Stop
        Add-LocalGroupMember -Group 'Administrateurs' -Member $u
        if ($dd) { Disable-LocalUser -Name 'Administrator' -ErrorAction SilentlyContinue }
    } -ArgumentList $Username, $secPwd, $DisableDefault.IsPresent
    Write-SysLog "Compte local admin $Username créé sur $ComputerName | Default Admin désactivé : $($DisableDefault.IsPresent)"
}

function Get-LocalAdmins {
    param([string[]]$ComputerNames)
    foreach ($pc in $ComputerNames) {
        try {
            $admins = Invoke-Command -ComputerName $pc -ScriptBlock {
                Get-LocalGroupMember -Group 'Administrateurs' | Select-Object Name, PrincipalSource, ObjectClass
            }
            foreach ($a in $admins) {
                [PSCustomObject]@{ Computer=$pc; Account=$a.Name; Source=$a.PrincipalSource; Type=$a.ObjectClass }
            }
        } catch {
            [PSCustomObject]@{ Computer=$pc; Account='ERROR'; Source=$_.Exception.Message; Type='' }
        }
    }
}

function Invoke-RemoteScript {
    param(
        [string[]]$ComputerNames,
        [ScriptBlock]$ScriptBlock,
        [object[]]$Arguments = @(),
        [int]$ThrottleLimit = 10
    )
    $jobs = Invoke-Command -ComputerName $ComputerNames -ScriptBlock $ScriptBlock `
        -ArgumentList $Arguments -ThrottleLimit $ThrottleLimit -AsJob
    $results = Receive-Job $jobs -Wait -AutoRemoveJob
    foreach ($pc in $ComputerNames) {
        $r = $results | Where-Object { $_.PSComputerName -eq $pc }
        if ($r) { [PSCustomObject]@{ Computer=$pc; Result=$r; Error=$null } }
        else    { [PSCustomObject]@{ Computer=$pc; Result=$null; Error='No response' } }
    }
    Write-SysLog "Script distant exécuté sur $($ComputerNames.Count) poste(s)"
}

function Export-AuditReport {
    param(
        [PSObject[]]$Data,
        [string]$Title,
        [string]$OutputDir = 'C:\\Reports',
        [string[]]$Format = @('CSV','HTML')
    )
    if (-not (Test-Path $OutputDir)) { New-Item -ItemType Directory $OutputDir -Force | Out-Null }
    $ts    = Get-Date -Format 'yyyyMMdd_HHmmss'
    $base  = Join-Path $OutputDir "${Title}_${ts}"
    $files = @()
    if ('CSV' -in $Format) { $csv = "$base.csv"; $Data | Export-Csv $csv -NoTypeInformation -Encoding UTF8; $files += $csv }
    if ('HTML' -in $Format) {
        $html = "$base.html"
        $rows = $Data | ConvertTo-Html -Title $Title -PreContent "<h2>$Title</h2><p>Généré le $(Get-Date)</p>" `
            -PostContent '<style>body{font-family:Consolas;} table{border-collapse:collapse;} td,th{border:1px solid #333;padding:4px;} tr:nth-child(even){background:#f2f2f2;}</style>'
        $rows | Out-File $html -Encoding UTF8
        $files += $html
    }
    Write-SysLog "Rapport exporté : $($files -join ' | ')"
    return $files
}
